probabilities.code:
export function probabilities(r: Vec3, n: Vec3): { plus: number; minus: number } {
  state(r);
  const direction = unit(n);
  // Tr(rho P+) = (1 + r · n)/2. Clamp only boundary roundoff.
  const plus = Math.max(0, Math.min(1, (1 + dot(r, direction)) / 2));
  return { plus, minus: 1 - plus };
}

rotate.code:
export function rotate(r: Vec3, n: Vec3, angle: number): Vec3 {
  state(r);
  const a = unit(n);
  finite(angle, 'rotation angle');
  const c = Math.cos(angle), s = Math.sin(angle);
  const parallel = dot(a, r) * (1 - c);
  const cross: Vec3 = [a[1] * r[2] - a[2] * r[1], a[2] * r[0] - a[0] * r[2], a[0] * r[1] - a[1] * r[0]];
  // U = exp(-i angle n · sigma / 2) acts as this spatial rotation.
  return [c * r[0] + s * cross[0] + parallel * a[0],
    c * r[1] + s * cross[1] + parallel * a[1],
    c * r[2] + s * cross[2] + parallel * a[2]];
}

spectral.code:
export function evolveSpectral(r: Vec3, h: Vec3, time: number): Vec3 {
  const rho = densityMatrix(r);
  const energy = norm(h);
  finite(time, 'physical time');
  if (energy === 0) return [r[0], r[1], r[2]];
  const phase = finite(energy * time, 'spectral phase');
  const [nx, ny, nz] = unit(h);
  const c = Math.cos(phase), s = Math.sin(phase);
  // Spectral sum U = exp(-iEt) P+ + exp(iEt) P-.
  const U: Matrix2 = [[complex(c, -s * nz), complex(-s * ny, -s * nx)],
    [complex(s * ny, -s * nx), complex(c, s * nz)]];
  const evolved = multiplyMatrices(multiplyMatrices(U, rho), adjoint(U));
  return [2 * evolved[0][1].re, -2 * evolved[0][1].im,
    evolved[0][0].re - evolved[1][1].re];
}

spectrum.code:
export function spectrum(h: Vec3): {
  energies: readonly [number, number]; lower: Vec3 | null; upper: Vec3 | null; gap: number;
} {
  const energy = norm(h);
  // At the degeneracy the eigenspace is the full space: no unique axis.
  if (energy === 0) return { energies: [0, 0], lower: null, upper: null, gap: 0 };
  const upper = unit(h);
  const lower: Vec3 = [-upper[0], -upper[1], -upper[2]];
  return { energies: [-energy, energy], lower, upper, gap: finite(2 * energy, 'energy gap') };
}

measure.code:
export function measure(r: Vec3, n: Vec3, draw: number): { outcome: Outcome; probability: number; state: Vec3 } {
  if (!Number.isFinite(draw) || draw < 0 || draw >= 1) throw new RangeError('A draw must lie in [0, 1)');
  const direction = unit(n);
  const p = probabilities(r, direction);
  const outcome: Outcome = draw < p.plus ? 1 : -1;
  // Conditioning on a rank-one Pauli outcome prepares its eigenstate.
  return { outcome, probability: outcome === 1 ? p.plus : p.minus,
    state: [outcome * direction[0], outcome * direction[1], outcome * direction[2]] };
}

box-wavefunction.code:
export function boxWavefunction(coeffs: readonly Complex[], x: number, params: BoxParameters): Complex {
  state(coeffs);
  parameters(params);
  finite(x, 'Position');
  let re = 0, im = 0;
  for (let j = 0; j < coeffs.length; j++) {
    const basis = boxEigenfunction(j + 1, x, params);
    re += coeffs[j].re * basis;
    im += coeffs[j].im * basis;
  }
  return { re, im };
}

box-evolution.code:
export function boxEvolve(coeffs: readonly Complex[], time: number, params: BoxParameters): Complex[] {
  state(coeffs);
  parameters(params);
  finite(time, 'Physical time');
  return coeffs.map((c, j) => {
    const phase = finite(boxEnergy(j + 1, params) * time, 'Spectral phase');
    const cosine = Math.cos(phase), sine = Math.sin(phase);
    // c_n(t) = c_n(0) exp(-i E_n t), with hbar = 1.
    return { re: c.re * cosine + c.im * sine,
      im: c.im * cosine - c.re * sine };
  });
}

box-energy-measurement.code:
export function measureBoxEnergy(coeffs: readonly Complex[], params: BoxParameters, draw: number): {
  n: number; energy: number; probability: number; state: Complex[];
} {
  state(coeffs);
  parameters(params);
  if (!Number.isFinite(draw) || draw < 0 || draw >= 1) throw new RangeError('A draw must lie in [0,1)');
  const weights = coeffs.map((c) => c.re ** 2 + c.im ** 2);
  const total = weights.reduce((sum, weight) => sum + weight, 0);
  let cumulative = 0, selected = 0;
  for (let j = 0; j < weights.length; j++) {
    if (weights[j] > 0) selected = j; // Last positive weight is the roundoff fallback.
    cumulative += weights[j];
    if (draw * total < cumulative) { selected = j; break; }
  }
  const magnitude = Math.sqrt(weights[selected]);
  const collapsed = coeffs.map((c, j) => j === selected ? { re: c.re / magnitude, im: c.im / magnitude } : { re: 0, im: 0 });
  return { n: selected + 1, energy: boxEnergy(selected + 1, params),
    probability: weights[selected] / total, state: collapsed };
}

oscillator-coherent.code:
export function coherentCoefficients(alpha: Complex, count: number): { coeffs: Complex[]; retainedWeight: number } {
  if (!Number.isInteger(count) || count < 1 || count > MAX_OSC_MODES) throw new RangeError('basis size must be 1–32');
  if (![alpha.re, alpha.im].every(Number.isFinite) || abs2(alpha) > 25) throw new RangeError('invalid coherent amplitude');
  const prefactor = Math.exp(-abs2(alpha) / 2), coeffs: Complex[] = [];
  let power: Complex = { re: 1, im: 0 }, sqrtFact = 1;
  for (let n = 0; n < count; n++) {
    if (n > 0) {
      const old = power;
      power = { re: old.re * alpha.re - old.im * alpha.im, im: old.re * alpha.im + old.im * alpha.re };
      sqrtFact *= Math.sqrt(n);
    }
    coeffs.push({ re: prefactor * power.re / sqrtFact, im: prefactor * power.im / sqrtFact });
  }
  const retainedWeight = coeffs.reduce((s, z) => s + abs2(z), 0);
  return { coeffs: normalizeOscillator(coeffs), retainedWeight };
}

oscillator-ritz.code:
export function rayleighRitzGround(count: number, coupling: number): AnharmonicRun {
  const h = anharmonicHamiltonian(count, coupling), eig = jacobiEigen(h), vector = eig.vectors[0], energy = eig.values[0];
  const hv = h.map(row => row.reduce((s, value, j) => s + value * vector[j], 0));
  const residual = Math.sqrt(hv.reduce((s, value, i) => s + (value - energy * vector[i]) ** 2, 0));
  const moments = oscillatorMoments(vector.map(re => ({ re, im: 0 })), { mass: 1, omega: 1 });
  return { coupling, basisSize: count, energy, vector: [...vector], residual, x2: moments.varianceX + moments.meanX * moments.meanX };
}

oscillator-variational.code:
export function optimizeGaussian(coupling: number, beta0: number, step: number, iterations: number): VariationalRun {
  if (!Number.isInteger(iterations) || iterations < 1 || iterations > 500 || !Number.isFinite(step) || step <= 0 || step > 2 || !Number.isFinite(beta0) || beta0 <= 0 || beta0 > 20) throw new RangeError('invalid optimizer settings');
  let beta = beta0; const points: VariationalPoint[] = [];
  for (let k = 0; k <= iterations; k++) {
    const energy = gaussianEnergy(beta, coupling), gradient = gaussianGradient(beta, coupling);
    points.push({ iteration: k, beta, energy, gradient });
    if (k === iterations) break;
    let trialStep = step;
    let next = beta;
    for (let attempt = 0; attempt < 12; attempt++) {
      const candidate = Math.max(0.05, Math.min(20, beta - trialStep * gradient));
      if (gaussianEnergy(candidate, coupling) <= energy) { next = candidate; break; }
      trialStep *= 0.5;
    }
    beta = next;
  }
  return { coupling, beta0, step, iterations, points };
}
